    def call(self, retref, rettype, argtypes=None, argrefs=None):
        if self.collector:
            self.collector.call(retref, rettype, argtypes, argrefs)
        else:
            self.codewriter.call(retref, rettype, argtypes=argtypes, argrefs=argrefs)

    def __iter__(self):
        for _ in range(self.num_threads):
            self.call(retref, rettype, argtypes=None)

    def get_collector(self):
        return self.collector
